20	export const useFolderTrust = (
21	  settings: LoadedSettings,
22	  onTrustChange: (isTrusted: boolean | undefined) => void,
23	  addItem: (item: HistoryItemWithoutId, timestamp: number) => number,
24	) => {
25	  const [isTrusted, setIsTrusted] = useState<boolean | undefined>(undefined);
26	  const [isFolderTrustDialogOpen, setIsFolderTrustDialogOpen] = useState(false);
27	  const [isRestarting, setIsRestarting] = useState(false);
28	  const startupMessageSent = useRef(false);
29	
30	  const folderTrust = settings.merged.security.folderTrust.enabled ?? true;
31	
32	  useEffect(() => {
33	    let isMounted = true;
34	    const { isTrusted: trusted } = isWorkspaceTrusted(settings.merged);
35	
36	    const showUntrustedMessage = () => {
37	      if (trusted === false && !startupMessageSent.current) {
38	        addItem(
39	          {
40	            type: MessageType.INFO,
41	            text: 'This folder is untrusted, project settings, hooks, MCPs, and GEMINI.md files will not be applied for this folder.\nUse the `/permissions` command to change the trust level.',
42	          },
43	          Date.now(),
44	        );
45	        startupMessageSent.current = true;
46	      }
47	    };
48	
49	    if (isHeadlessMode()) {
50	      if (isMounted) {
51	        setIsTrusted(trusted);
52	        setIsFolderTrustDialogOpen(false);
53	        onTrustChange(true);
54	        showUntrustedMessage();
55	      }
56	    } else if (isMounted) {
57	      setIsTrusted(trusted);
58	      setIsFolderTrustDialogOpen(trusted === undefined);
59	      onTrustChange(trusted);
60	      showUntrustedMessage();
61	    }
62	
63	    return () => {
64	      isMounted = false;
65	    };
66	  }, [folderTrust, onTrustChange, settings.merged, addItem]);
67	
68	  const handleFolderTrustSelect = useCallback(
69	    async (choice: FolderTrustChoice) => {
70	      const trustLevelMap: Record<FolderTrustChoice, TrustLevel> = {
71	        [FolderTrustChoice.TRUST_FOLDER]: TrustLevel.TRUST_FOLDER,
72	        [FolderTrustChoice.TRUST_PARENT]: TrustLevel.TRUST_PARENT,
73	        [FolderTrustChoice.DO_NOT_TRUST]: TrustLevel.DO_NOT_TRUST,
74	      };
75	
76	      const trustLevel = trustLevelMap[choice];
77	      if (!trustLevel) return;
78	
79	      const cwd = process.cwd();
80	      const trustedFolders = loadTrustedFolders();
81	
82	      try {
83	        await trustedFolders.setValue(cwd, trustLevel);
84	      } catch (_e) {
85	        coreEvents.emitFeedback(
86	          'error',
87	          'Failed to save trust settings. Exiting Gemini CLI.',
88	        );
89	        setTimeout(async () => {
90	          await runExitCleanup();
91	          process.exit(ExitCodes.FATAL_CONFIG_ERROR);
92	        }, 100);
93	        return;
94	      }
95	
96	      const currentIsTrusted =
97	        trustLevel === TrustLevel.TRUST_FOLDER ||
98	        trustLevel === TrustLevel.TRUST_PARENT;
99	
100	      onTrustChange(currentIsTrusted);
101	      setIsTrusted(currentIsTrusted);
102	
103	      // logic: we restart if the trust state *effectively* changes from the previous state.
104	      // previous state was `isTrusted`. If undefined, we assume false (untrusted).
105	      const wasTrusted = isTrusted ?? false;
106	
107	      if (wasTrusted !== currentIsTrusted) {
108	        setIsRestarting(true);
109	        setIsFolderTrustDialogOpen(true);
110	      } else {
111	        setIsFolderTrustDialogOpen(false);
112	      }
113	    },
114	    [onTrustChange, isTrusted],
115	  );
116	
117	  return {
118	    isTrusted,
119	    isFolderTrustDialogOpen,
120	    handleFolderTrustSelect,
121	    isRestarting,
122	  };
123	};
