90	 *
91	 * This should not be called from interactive mode as it will break the CLI.
92	 *
93	 * @param prompt A yes/no prompt to ask the user
94	 * @returns Whether or not the user answers 'y' (yes). Defaults to 'yes' on enter.
95	 */
96	async function promptForConsentNonInteractive(
97	  prompt: string,
98	): Promise<boolean> {
99	  const readline = await import('node:readline');
100	  const rl = readline.createInterface({
101	    input: process.stdin,
102	    output: process.stdout,
103	  });
104	
105	  return new Promise((resolve) => {
106	    rl.question(prompt, (answer) => {
107	      rl.close();
108	      resolve(['y', ''].includes(answer.trim().toLowerCase()));
109	    });
110	  });
111	}
