140	async function extensionConsentString(
141	  extensionConfig: ExtensionConfig,
142	  hasHooks: boolean,
143	  skills: SkillDefinition[] = [],
144	): Promise<string> {
145	  const sanitizedConfig = escapeAnsiCtrlCodes(extensionConfig);
146	  const output: string[] = [];
147	  const mcpServerEntries = Object.entries(sanitizedConfig.mcpServers || {});
148	  output.push(`Installing extension "${sanitizedConfig.name}".`);
149	
150	  if (mcpServerEntries.length) {
151	    output.push('This extension will run the following MCP servers:');
152	    for (const [key, mcpServer] of mcpServerEntries) {
153	      const isLocal = !!mcpServer.command;
154	      const source =
155	        mcpServer.httpUrl ??
156	        `${mcpServer.command || ''}${mcpServer.args ? ' ' + mcpServer.args.join(' ') : ''}`;
157	      output.push(`  * ${key} (${isLocal ? 'local' : 'remote'}): ${source}`);
158	    }
159	  }
160	  if (sanitizedConfig.contextFileName) {
161	    output.push(
162	      `This extension will append info to your gemini.md context using ${sanitizedConfig.contextFileName}`,
163	    );
164	  }
165	  if (sanitizedConfig.excludeTools) {
166	    output.push(
167	      `This extension will exclude the following core tools: ${sanitizedConfig.excludeTools}`,
168	    );
169	  }
170	  if (hasHooks) {
171	    output.push(
172	      '⚠️  This extension contains Hooks which can automatically execute commands.',
173	    );
174	  }
175	  if (skills.length > 0) {
176	    output.push(`\n${chalk.bold('Agent Skills:')}`);
177	    output.push('\nThis extension will install the following agent skills:\n');
178	    output.push(...(await renderSkillsList(skills)));
179	  }
180	
181	  output.push('\n' + INSTALL_WARNING_MESSAGE);
182	  if (skills.length > 0) {
183	    output.push('\n' + SKILLS_WARNING_MESSAGE);
184	  }
185	
186	  return output.join('\n');
187	}
