192	async function renderSkillsList(skills: SkillDefinition[]): Promise<string[]> {
193	  const output: string[] = [];
194	  for (const skill of skills) {
195	    output.push(`  * ${chalk.bold(skill.name)}: ${skill.description}`);
196	    const skillDir = path.dirname(skill.location);
197	    let fileCountStr = '';
198	    try {
199	      const skillDirItems = await fs.readdir(skillDir);
200	      fileCountStr = ` (${skillDirItems.length} items in directory)`;
201	    } catch {
202	      fileCountStr = ` ${chalk.red('⚠️ (Could not count items in directory)')}`;
203	    }
204	    output.push(chalk.dim(`    (Source: ${skill.location})${fileCountStr}`));
205	    output.push('');
206	  }
207	  return output;
208	}
