import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { GEMINI_DIR } from '../utils/paths.js';

/**
 * A summary of the configurations discovered inside a project's `.gemini`
 * directory. This is surfaced to the user in the folder trust dialog so they
 * can make an informed decision before trusting a folder.
 */
export interface FolderDiscoveryResults {
  /** Names of custom commands (`.toml` files without their extension). */
  commands: string[];
  /** Names of MCP servers configured in `settings.json`. */
  mcps: string[];
  /** Command strings configured via the `hooks` key in `settings.json`. */
  hooks: string[];
  /** Names of agent skills (subdirectories containing a `SKILL.md`). */
  skills: string[];
  /**
   * Top-level `settings.json` keys (excluding `mcpServers` and `hooks`, which
   * are reported separately).
   */
  settings: string[];
  /** Human-readable warnings about potentially risky configurations. */
  securityWarnings: string[];
  /** Errors encountered while scanning the folder (e.g. malformed JSON). */
  discoveryErrors: string[];
}

const SETTINGS_FILE = 'settings.json';
const COMMANDS_DIR = 'commands';
const SKILLS_DIR = 'skills';
const SKILL_FILE = 'SKILL.md';

function createEmptyResults(): FolderDiscoveryResults {
  return {
    commands: [],
    mcps: [],
    hooks: [],
    skills: [],
    settings: [],
    securityWarnings: [],
    discoveryErrors: [],
  };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' && value !== null && !Array.isArray(value)
  );
}

/**
 * Scans a workspace's `.gemini` configuration directory and summarizes its
 * contents, flagging potentially risky settings so the user can make an
 * informed trust decision.
 */
export class FolderTrustDiscoveryService {
  static async discover(
    workspaceDir: string,
  ): Promise<FolderDiscoveryResults> {
    const results = createEmptyResults();
    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    // If there is no `.gemini` directory there is nothing to discover.
    try {
      const stats = await fs.stat(geminiDir);
      if (!stats.isDirectory()) {
        return results;
      }
    } catch {
      return results;
    }

    await FolderTrustDiscoveryService.discoverCommands(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSkills(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSettings(geminiDir, results);

    FolderTrustDiscoveryService.generateSecurityWarnings(results);

    return results;
  }

  private static async discoverCommands(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const commandsDir = path.join(geminiDir, COMMANDS_DIR);
    let entries: string[];
    try {
      entries = await fs.readdir(commandsDir);
    } catch {
      return;
    }

    for (const entry of entries) {
      if (entry.toLowerCase().endsWith('.toml')) {
        results.commands.push(path.basename(entry, path.extname(entry)));
      }
    }
  }

  private static async discoverSkills(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const skillsDir = path.join(geminiDir, SKILLS_DIR);
    let entries: Array<{ name: string; isDirectory: () => boolean }>;
    try {
      entries = await fs.readdir(skillsDir, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      if (!entry.isDirectory()) {
        continue;
      }
      const skillFile = path.join(skillsDir, entry.name, SKILL_FILE);
      try {
        const stats = await fs.stat(skillFile);
        if (stats.isFile()) {
          results.skills.push(entry.name);
        }
      } catch {
        // No SKILL.md in this subdirectory; skip it.
      }
    }
  }

  private static async discoverSettings(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const settingsPath = path.join(geminiDir, SETTINGS_FILE);
    let raw: string;
    try {
      raw = await fs.readFile(settingsPath, 'utf-8');
    } catch {
      // No settings.json is a perfectly valid state.
      return;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      results.discoveryErrors.push(
        `Failed to discover settings: ${message}`,
      );
      return;
    }

    // Non-object values (arrays, strings, numbers, null) don't contain any
    // settings we can meaningfully report.
    if (!isPlainObject(parsed)) {
      return;
    }

    if (isPlainObject(parsed['mcpServers'])) {
      results.mcps.push(...Object.keys(parsed['mcpServers']));
    }

    if (parsed['hooks'] !== undefined) {
      results.hooks.push(
        ...FolderTrustDiscoveryService.extractHookCommands(parsed['hooks']),
      );
    }

    results.settings.push(
      ...Object.keys(parsed).filter(
        (key) => key !== 'mcpServers' && key !== 'hooks',
      ),
    );
  }

  /**
   * Recursively collects every `command` string found within the `hooks`
   * configuration, regardless of the exact event/matcher shape used.
   */
  private static extractHookCommands(hooks: unknown): string[] {
    const commands: string[] = [];

    const visit = (value: unknown): void => {
      if (Array.isArray(value)) {
        for (const item of value) {
          visit(item);
        }
        return;
      }
      if (isPlainObject(value)) {
        if (typeof value['command'] === 'string') {
          commands.push(value['command']);
        }
        for (const child of Object.values(value)) {
          visit(child);
        }
      }
    };

    visit(hooks);
    return commands;
  }

  private static generateSecurityWarnings(
    results: FolderDiscoveryResults,
  ): void {
    if (results.mcps.length > 0) {
      results.securityWarnings.push(
        'This folder configures MCP servers that can run and communicate with external processes.',
      );
    }

    if (results.hooks.length > 0) {
      results.securityWarnings.push(
        'This folder contains hooks that can automatically execute commands on your system.',
      );
    }
  }
}
