56	  // Render up to 100% of the available terminal height (minus 1 line for safety)
57	  // to maximize space for diffs and other content.
58	  const maxHeight =
59	    uiAvailableHeight !== undefined
60	      ? Math.max(uiAvailableHeight - 1, 4)
61	      : Math.floor(terminalHeight * 0.5);
62	
63	  const isRoutine =
64	    tool.confirmationDetails?.type === 'ask_user' ||
65	    tool.confirmationDetails?.type === 'exit_plan_mode';
