72	  // - 2 lines for the Header (text + margin)
73	  // - 2 lines for Tool Identity (text + margin)
74	  const availableContentHeight =
75	    constrainHeight && !isAlternateBuffer
76	      ? Math.max(maxHeight - (hideToolIdentity ? 4 : 6), 4)
77	      : undefined;
78	
