92	              justifyContent="space-between"
93	            >
94	              <Text color={borderColor} bold>
95	                {getConfirmationHeader(tool.confirmationDetails)}
96	              </Text>
97	              {total > 1 && (
98	                <Text color={theme.text.secondary}>
99	                  {index} of {total}
100	                </Text>
101	              )}
102	            </Box>
103	
104	            {!hideToolIdentity && (
105	              <Box>
106	                <ToolStatusIndicator status={tool.status} name={tool.name} />
107	                <ToolInfo
108	                  name={tool.name}
109	                  status={tool.status}
110	                  description={tool.description}
111	                  emphasis="high"
112	                />
113	              </Box>
114	            )}
115	          </Box>
116	        </StickyHeader>
117	
118	        <Box
119	          width={mainAreaWidth}
120	          borderStyle="round"
121	          borderColor={borderColor}
122	          borderTop={false}
123	          borderBottom={false}
124	          borderLeft={true}
125	          borderRight={true}
126	          paddingX={1}
127	          flexDirection="column"
128	        >
129	          {/* Interactive Area */}
