136	            confirmationDetails={tool.confirmationDetails}
137	            config={config}
138	            terminalWidth={mainAreaWidth - 4} // Adjust for parent border/padding
139	            availableTerminalHeight={availableContentHeight}
140	            isFocused={true}
141	          />
142	        </Box>
143	        <Box
144	          height={1}
145	          width={mainAreaWidth}
146	          borderLeft={true}
147	          borderRight={true}
148	          borderTop={false}
149	          borderBottom={true}
150	          borderColor={borderColor}
151	          borderStyle="round"
152	        />
153	      </Box>
154	      <ShowMoreLines constrainHeight={constrainHeight} />
155	    </OverflowProvider>
