import { Box, Text } from 'ink';
import type React from 'react';
import { useEffect, useState, useCallback } from 'react';
import stripAnsi from 'strip-ansi';
import { theme } from '../semantic-colors.js';
import type { RadioSelectItem } from './shared/RadioButtonSelect.js';
import { RadioButtonSelect } from './shared/RadioButtonSelect.js';
import { useKeypress } from '../hooks/useKeypress.js';
import * as process from 'node:process';
import * as path from 'node:path';
import { relaunchApp } from '../../utils/processUtils.js';
import { runExitCleanup } from '../../utils/cleanup.js';
import { ExitCodes, type FolderDiscoveryResults } from '@google/gemini-cli-core';
import { useUIState } from '../contexts/UIStateContext.js';
import { useAlternateBuffer } from '../hooks/useAlternateBuffer.js';
import { OverflowProvider } from '../contexts/OverflowContext.js';
import { MaxSizedBox } from './shared/MaxSizedBox.js';
import { ShowMoreLines } from './ShowMoreLines.js';
import { Scrollable } from './shared/Scrollable.js';

export enum FolderTrustChoice {
  TRUST_FOLDER = 'trust_folder',
  TRUST_PARENT = 'trust_parent',
  DO_NOT_TRUST = 'do_not_trust',
}

interface FolderTrustDialogProps {
  onSelect: (choice: FolderTrustChoice) => void;
  isRestarting?: boolean;
  discoveryResults?: FolderDiscoveryResults | null;
}

interface DiscoveryCategory {
  label: string;
  items: string[];
}

/** Removes ANSI escape codes so untrusted config values can't manipulate the terminal. */
const clean = (value: string): string => stripAnsi(value);

/** Whether the discovery results contain anything worth displaying. */
const hasDiscoveryContent = (results: FolderDiscoveryResults): boolean =>
  results.commands.length > 0 ||
  results.mcps.length > 0 ||
  results.hooks.length > 0 ||
  results.skills.length > 0 ||
  results.settings.length > 0 ||
  results.securityWarnings.length > 0 ||
  results.discoveryErrors.length > 0;

const DiscoverySummary: React.FC<{ results: FolderDiscoveryResults }> = ({
  results,
}) => {
  const categories: DiscoveryCategory[] = [
    { label: 'Commands', items: results.commands },
    { label: 'MCP Servers', items: results.mcps },
    { label: 'Hooks', items: results.hooks },
    { label: 'Skills', items: results.skills },
    { label: 'Settings', items: results.settings },
  ];

  const nonEmptyCategories = categories.filter(
    (category) => category.items.length > 0,
  );

  const hasContents = nonEmptyCategories.length > 0;
  const hasWarnings = results.securityWarnings.length > 0;
  const hasErrors = results.discoveryErrors.length > 0;

  if (!hasContents && !hasWarnings && !hasErrors) {
    return null;
  }

  return (
    <Box flexDirection="column" marginBottom={1}>
      {hasContents && (
        <Box flexDirection="column">
          <Text bold color={theme.text.primary}>
            This folder contains:
          </Text>
          {nonEmptyCategories.map((category) => (
            <Box key={category.label} flexDirection="row">
              <Text color={theme.text.secondary}>
                {`  ${category.label} (${category.items.length}): `}
              </Text>
              <Text color={theme.text.primary} wrap="wrap">
                {category.items.map(clean).join(', ')}
              </Text>
            </Box>
          ))}
        </Box>
      )}

      {hasWarnings && (
        <Box flexDirection="column" marginTop={hasContents ? 1 : 0}>
          <Text bold color={theme.status.warning}>
            Security Warnings:
          </Text>
          {results.securityWarnings.map((warning, index) => (
            <Text key={index} color={theme.status.warning} wrap="wrap">
              {`  ⚠ ${clean(warning)}`}
            </Text>
          ))}
        </Box>
      )}

      {hasErrors && (
        <Box
          flexDirection="column"
          marginTop={hasContents || hasWarnings ? 1 : 0}
        >
          <Text bold color={theme.status.error}>
            Discovery Errors:
          </Text>
          {results.discoveryErrors.map((error, index) => (
            <Text key={index} color={theme.status.error} wrap="wrap">
              {`  ✗ ${clean(error)}`}
            </Text>
          ))}
        </Box>
      )}
    </Box>
  );
};

export const FolderTrustDialog: React.FC<FolderTrustDialogProps> = ({
  onSelect,
  isRestarting,
  discoveryResults,
}) => {
  const [exiting, setExiting] = useState(false);
  const isAlternateBuffer = useAlternateBuffer();
  const { terminalHeight, availableTerminalHeight, constrainHeight } =
    useUIState();

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isRestarting) {
      timer = setTimeout(async () => {
        await relaunchApp();
      }, 250);
    }
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [isRestarting]);

  const handleExit = useCallback(() => {
    setExiting(true);
    // Give time for the UI to render the exiting message
    setTimeout(async () => {
      await runExitCleanup();
      process.exit(ExitCodes.FATAL_CANCELLATION_ERROR);
    }, 100);
  }, []);

